fn inject_binding_unchecked(b: KeyBinding) { unsafe { if b.kind == BindKind::None { return; } if b.kind == BindKind::Mouse { let (down, up, data) = match b.mouse_button { 1 => (MOUSEEVENTF_LEFTDOWN, MOUSEEVENTF_LEFTUP, 0), 2 => (MOUSEEVENTF_RIGHTDOWN, MOUSEEVENTF_RIGHTUP, 0), 3 => (MOUSEEVENTF_MIDDLEDOWN, MOUSEEVENTF_MIDDLEUP, 0), 4 => (MOUSEEVENTF_XDOWN, MOUSEEVENTF_XUP, XBUTTON1 as u32), 5 => (MOUSEEVENTF_XDOWN, MOUSEEVENTF_XUP, XBUTTON2 as u32), _ => return, }; let make = |flags| INPUT { r#type: INPUT_MOUSE, Anonymous: INPUT_0 { mi: MOUSEINPUT { dx:0, dy:0, mouseData:data, dwFlags:flags, time:0, dwExtraInfo:INJECTED_TAG } }, }; let inputs = [make(down), make(up)]; SendInput(2, inputs.as_ptr(), size_of::<INPUT>() as i32); } else { let mut scan = b.scan; if scan == 0 { scan = MapVirtualKeyW(b.vk as u32, MAPVK_VK_TO_VSC_EX) as u16; if scan == 0 { scan = MapVirtualKeyW(b.vk as u32, MAPVK_VK_TO_VSC) as u16; } } let mut base_flags = KEYEVENTF_SCANCODE; if b.extended || (scan & 0xFF00) == 0xE000 { base_flags |= KEYEVENTF_EXTENDEDKEY; } let scan_code = scan & 0x00FF; let make = |up: bool| INPUT { r#type: INPUT_KEYBOARD, Anonymous: INPUT_0 { ki: KEYBDINPUT { wVk: 0, wScan: scan_code, dwFlags: base_flags | if up {KEYEVENTF_KEYUP} else {0}, time:0, dwExtraInfo:INJECTED_TAG, } }, }; let inputs = [make(false), make(true)]; SendInput(2, inputs.as_ptr(), size_of::<INPUT>() as i32); } } } 
fn normalize_keyboard(vk: u16, make: u16, flags: u16) -> KeyBinding { let extended = (flags & 0x02) != 0; let mut v = vk; if vk == VK_SHIFT as u16 { v = if make == 0x36 { VK_RSHIFT as u16 } else { VK_LSHIFT as u16 }; } if vk == VK_CONTROL as u16 { v = if extended { VK_RCONTROL as u16 } else { VK_LCONTROL as u16 }; } if vk == VK_MENU as u16 { v = if extended { VK_RMENU as u16 } else { VK_LMENU as u16 }; } KeyBinding { kind: BindKind::Keyboard, vk: v, scan: make, extended, mouse_button: 0 } } 
unsafe fn register_raw_input(hwnd: HWND) -> bool { let devices = [ RAWINPUTDEVICE { usUsagePage: 0x01, usUsage: 0x02, dwFlags: RIDEV_INPUTSINK, hwndTarget: hwnd }, RAWINPUTDEVICE { usUsagePage: 0x01, usUsage: 0x06, dwFlags: RIDEV_INPUTSINK, hwndTarget: hwnd }, ]; RegisterRawInputDevices(devices.as_ptr(), devices.len() as u32, size_of::<RAWINPUTDEVICE>() as u32) != 0 } 
unsafe fn handle_raw_input(lparam: LPARAM) { let mut size = 0u32; GetRawInputData(lparam as _, RID_INPUT, null_mut(), &mut size, size_of::<windows_sys::Win32::UI::Input::RAWINPUTHEADER>() as u32); if size == 0 { return; } let mut buf = vec![0usize; (size as usize).div_ceil(size_of::<usize>())]; if GetRawInputData(lparam as _, RID_INPUT, buf.as_mut_ptr() as *mut c_void, &mut size, size_of::<windows_sys::Win32::UI::Input::RAWINPUTHEADER>() as u32) == u32::MAX { return; } let raw = &*(buf.as_ptr() as *const RAWINPUT); if raw.header.dwType == RIM_TYPEKEYBOARD { let k = raw.data.keyboard; if k.ExtraInformation as usize == (INJECTED_TAG & 0xffff_ffff) { return; } if k.VKey == 255 { return; } let down = k.Message == WM_KEYDOWN || k.Message == WM_SYSKEYDOWN; let up = k.Message == WM_KEYUP || k.Message == WM_SYSKEYUP; if down || up { process_binding_event(normalize_keyboard(k.VKey, k.MakeCode, k.Flags), down, up); } } else if raw.header.dwType == RIM_TYPEMOUSE { let m = raw.data.mouse; if m.ulExtraInformation as usize == (INJECTED_TAG & 0xffff_ffff) { return; } let flags = m.Anonymous.Anonymous.usButtonFlags; let tests = [ (RI_MOUSE_LEFT_BUTTON_DOWN as u16, RI_MOUSE_LEFT_BUTTON_UP as u16, 1u8), (RI_MOUSE_RIGHT_BUTTON_DOWN as u16, RI_MOUSE_RIGHT_BUTTON_UP as u16, 2u8), (RI_MOUSE_MIDDLE_BUTTON_DOWN as u16, RI_MOUSE_MIDDLE_BUTTON_UP as u16, 3u8), (RI_MOUSE_BUTTON_4_DOWN as u16, RI_MOUSE_BUTTON_4_UP as u16, 4u8), (RI_MOUSE_BUTTON_5_DOWN as u16, RI_MOUSE_BUTTON_5_UP as u16, 5u8), ]; for (d,u,b) in tests { if flags & d != 0 { process_binding_event(KeyBinding::mouse(b), true, false); } if flags & u != 0 { process_binding_event(KeyBinding::mouse(b), false, true); } } } } 
